parameters.jsCode:
const request = $('Get row(s) in sheet').item.json;
const employee = $json;

// Leave information from employee request
// const leaveType = request.leaveType;
// const requestedDays = Number(request.requestedDays);
$('Edit Fields').first().json['Leave Type']
const leaveType =$('Edit Fields').first().json['Leave Type'] ;
const requestedDays =  $('Edit Fields').first().json.requestedDays;

// Get available leave balance
let availableBalance = 0;

if (leaveType === 'Casual') {
  availableBalance = Number(employee['Causal Leave'] || 0);
}
else if (leaveType === 'Sick') {
  availableBalance = Number(employee['Sick Leave'] || 0);
}
else if (leaveType === 'Earned') {
  availableBalance = Number(employee['Earned Leave'] || 0);
}

// Check whether employee has enough balance
const balanceAvailable = availableBalance >= requestedDays;

// Calculate remaining balance
const remainingBalance = availableBalance - requestedDays;

// Return combined data
return {
  json: {
    requestId: request.requestId || `LR-${Date.now()}`,

    employeeId: employee['Employee ID'],
    employeeName: employee['Employee Name'],
    email: employee['Employee Email'],

    leaveType: leaveType,
    fromDate: request.fromDate,
    toDate: request.toDate,
    requestedDays: requestedDays,
    reason: request.reason,

    availableBalance: availableBalance,
    remainingBalance: remainingBalance,
    balanceAvailable: balanceAvailable,

    managerName: employee['Manager Name'],
    managerEmail: employee['Manager Email']
  }
};

