parameters.jsCode:
const text = $json.content?.parts?.[0]?.text || '';

return {
  json: {
    ...$json,
    managerMessage: text
  }
};

const now = new Date();

const date =
  now.getFullYear().toString() +
  String(now.getMonth() + 1).padStart(2, '0') +
  String(now.getDate()).padStart(2, '0');

const random = Math.floor(1000 + Math.random() * 9000);

const requestId = `LR-${date}-${random}`;

return {
  json: {
    ...$json,
    requestId
  }
};

const email = $json;

const messageId = email.id;
const threadId = email.threadId;

// Gmail field names are capitalized in your output
const managerEmail = email.From || '';
const subject = email.Subject || '';

// Email body/reply is available in snippet
const snippet = email.snippet || '';

let managerReply = '';

// Extract the new reply from the beginning of the snippet
// Example: "APPROVED On Mon, Sep 7, 2026 at 12:40 PM..."
managerReply = snippet
  .split(/\s+On\s+\w{3},/i)[0]
  .trim();

return {
  json: {
    messageId,
    threadId,
    managerEmail,
    subject,
    managerReply
  }
};

const reply = $('Code in JavaScript3').first().json.managerReply

let approvalStatus = 'Unknown';

if (
  reply === 'APPROVED' ||
  reply.includes('APPROVED')
) {
  approvalStatus = 'Approved';
}
else if (
  reply === 'REJECTED' ||
  reply.includes('REJECT')
) {
  approvalStatus = 'Rejected';
}

return {
  json: {
    ...$json,
    managerReply: reply,
    approvalStatus
  }
};

